def detect_non_silence(x: np.ndarray, threshold: float=0.01, frame_length: int=1024, frame_shift: int=512, window: str='boxcar') -> np.ndarray:
    """Power based voice activity detection.

    Args:
        x: (Channel, Time)
    >>> x = np.random.randn(1000)
    >>> detect = detect_non_silence(x)
    >>> assert x.shape == detect.shape
    >>> assert detect.dtype == np.bool
    """
    if x.shape[-1] < frame_length:
        return np.full(x.shape, fill_value=True, dtype=np.bool)
    if x.dtype.kind == 'i':
        x = x.astype(np.float64)
    framed_w = framing(x, frame_length=frame_length, frame_shift=frame_shift, centered=False, padded=True)
    framed_w *= scipy.signal.get_window(window, frame_length).astype(framed_w.dtype)
    power = (framed_w ** 2).mean(axis=-1)
    mean_power = np.mean(power, axis=-1, keepdims=True)
    if np.all(mean_power == 0):
        return np.full(x.shape, fill_value=True, dtype=np.bool)
    detect_frames = power / mean_power > threshold
    detects = np.broadcast_to(detect_frames[..., None], detect_frames.shape + (frame_shift,))
    detects = detects.reshape(*detect_frames.shape[:-1], -1)
    return np.pad(detects, [(0, 0)] * (x.ndim - 1) + [(0, x.shape[-1] - detects.shape[-1])], mode='edge')

