    param_group_names = {}
    param_groups = {}
    num_layers = len(model.blocks) + 2
    layer_scales = list((layer_decay ** (num_layers - i) for i in range(num_layers + 1)))
    for n, p in model.named_parameters():
        if not p.requires_grad:
