        if p.ndim == 1 or n in no_weight_decay_list:
            g_decay = 'no_decay'
            this_decay = 0.0
        else:
            g_decay = 'decay'
            this_decay = weight_decay
        layer_id = get_layer_id_for_model(n, num_layers)
        group_name = 'layer_%d_%s' % (layer_id, g_decay)
        if group_name not in param_group_names:
            this_scale = layer_scales[layer_id]
            param_group_names[group_name] = {'lr_scale': this_scale, 'weight_decay': this_decay, 'params': []}
            param_groups[group_name] = {'lr_scale': this_scale, 'weight_decay': this_decay, 'params': []}
        print('name: %s, layer_id: %d, group_name: %s, lr_scale: %f, weight_decay: %f' % (n, layer_id, group_name, param_group_names[group_name]['lr_scale'], param_group_names[group_name]['weight_decay']))
        param_group_names[group_name]['params'].append(n)
        param_groups[group_name]['params'].append(p)
