def crop(image: Image.Image, ratio: float) -> Image.Image:
    """Crop images so they have the same aspect ratio."""
    w, h = image.size
    if w / h < ratio:
        h_new = int(w / ratio)
        image = image.crop((0, (h - h_new) // 2, w, h - (h - h_new) // 2))
    else:
        w_new = int(h * ratio)
        image = image.crop(((w - w_new) // 2, 0, w - (w - w_new) // 2, h))
    return image

def compute_backward_flow(surfaces: Float[Tensor, 'batch frame *grid xyz=3'], extrinsics: Float[Tensor, 'batch frame 4 4'], intrinsics: Float[Tensor, 'batch frame 3 3']) -> Float[Tensor, 'batch frame-1 *grid xy=2']:
    """Return the positions of all surface points with backward optical flow applied."""
    backward_transformation = earlier(extrinsics).inverse() @ later(extrinsics)
    singletons = ' '.join(['()'] * (surfaces.ndim - 3))
    pattern = f'b f i j -> b f {singletons} i j'
    return reproject_points(later(surfaces), rearrange(backward_transformation, pattern), rearrange(earlier(intrinsics), pattern))

def read_next_bytes(fid, num_bytes, format_char_sequence, endian_character='<'):
    """Read and unpack the next bytes from a binary file.
    :param fid:
    :param num_bytes: Sum of combination of {2, 4, 8}, e.g. 2, 6, 16, 30, etc.
    :param format_char_sequence: List of {c, e, f, d, h, H, i, I, l, L, q, Q}.
    :param endian_character: Any of {@, =, <, >, !}
    :return: Tuple of read and unpacked values.
    """
    data = fid.read(num_bytes)
    return struct.unpack(endian_character + format_char_sequence, data)

