def gen_bearings_from_waypoints(waypoints: np.ndarray, mag=0.2) -> np.ndarray:
    """Generate bearings from waypoints, (x, y, sin(theta), cos(theta))."""
    bearing = []
    for i in range(0, len(waypoints)):
        if waypoints.shape[1] > 3:
            v = waypoints[i, 2:]
            v = v / np.linalg.norm(v)
            v = v * mag
